app.get("/api/config", (_req, res) => {
  res.json({ success: true, yearId: YEAR_ID });
});

app.get("/api/subjects", async (_req, res) => {
  try { res.json(await upstreamJson(`/user/subjects/${YEAR_ID}`)); }
  catch (e) { jsonError(res, 502, e.message); }
});

